import { createPortal } from 'react-dom';

function Modal({ children }) {
  return createPortal(
    <div className='modal'>{children}</div>,
    document.body
  );
}

function Price({ value, currency = 'BRL' }) {
  const text = value.toLocaleString('pt-BR', {
    style: 'currency',
    currency,
  });
  return <strong>{text}</strong>;
}

function Likes() {
  const [likes, setLikes] = useState(0);

  return (
    <button onClick={() => setLikes(likes + 1)}>
      {likes} curtidas
    </button>
  );
}

type Props = {
  name: string;
  size?: number;
};

function Avatar({ name, size = 32 }: Props) {
  return <img alt={name} width={size} />;
}

function Search() {
  const [q, setQ] = useState<string>('');

  function onChange(e: ChangeEvent<HTMLInputElement>) {
    setQ(e.target.value);
  }

  return <input value={q} onChange={onChange} />;
}

